async def obtain_recording_input(context: InputContext) -> InputStep:
    """取得录像内部输入副本：资格、续传、分段与完整性收尾。

    资格等待或最终失败时不开始拷贝；已完成副本重入直接就绪。会话
    在段循环结束后无论成败都请求停止并等待实际结束；段保存跳过表
    示发起责任不再执行，本次停止推进。摘要不一致登记新一轮重拷后
    不就地重试，由下一次执行从零重读。
    """
    receipt = await context.copies.qualify(FileCandidate(
        action_id=context.action_id,
        item_id=None,
        processing_id=context.processing_id,
        output_id=None,
        source_device_file_id=context.source_device_file_id,
        target_extension=context.target_extension,
        delivery_extension=None,
        delivery_display_name=None,
        config=context.config,
        occurred_at=context.occurred_at,
        inspection_id=context.inspection_id,
    ))
    if receipt.disposition is SaveDisposition.REJECTED:
        return InputStep(InputPhase.QUALIFY_REJECTED, error=receipt.error)
    if receipt.disposition is SaveDisposition.UNKNOWN:
        return InputStep(InputPhase.QUALIFY_UNKNOWN, error=receipt.error)
    qualification = receipt.value
    if qualification.outcome is QualificationOutcome.REJECTED_FINAL:
        return InputStep(InputPhase.REJECTED_FINAL, reason=qualification.reason)
    if qualification.outcome is not QualificationOutcome.GRANTED:
        return InputStep(InputPhase.WAITING, reason=qualification.reason)
    copy_id = qualification.copy_id

    facts = await context.copies.copy_state(copy_id)
    if (facts.verification_state in _READY_VERIFICATIONS
            and facts.target_sha256 is not None):
        return InputStep(
            InputPhase.INPUT_READY, copy_id=copy_id,
            input_file=_input_ref(facts, context.staging))

    try:
        prepared = await context.copies.prepare(copy_id)
    except (CopyPreparationError, ConsistencyError) as error:
        return InputStep(InputPhase.PREPARE_FAILED, copy_id=copy_id,
                         error=error)

    if prepared.decision.outcome is ResumeOutcome.VERIFY and context.read_end is not None:
        return replace(await _complete_input(context, copy_id, facts), read_end=context.read_end,
                       stop_requested=True, content_complete=True)

    try:
        session = await context.sessions.open_session(
            context.source_device_file_id, facts.source_size if prepared.decision.outcome is ResumeOutcome.VERIFY
            else prepared.decision.offset, on_start=context.on_read_start)
        from camctl.outputs.read_attempts import ReadDispatchPrevented
        if isinstance(session, ReadDispatchPrevented):
            return InputStep(InputPhase.READ_NOT_STARTED, copy_id=copy_id,
                reason=session.reason, dispatch_prevented=session)
    except Exception as error:
        settlement = (error.settlement if isinstance(error, ReadPreparationError)
                      else ReadPreparationSettlement.SETTLED)
        return InputStep(InputPhase.WAITING if settlement is ReadPreparationSettlement.WAITING else InputPhase.SEGMENT_FAILED,
                         copy_id=copy_id, error=error,
                         source_failed=settlement is ReadPreparationSettlement.SETTLED,
                         preparation_settlement=settlement)
    result = None
    execution_error = None
    try:
        if prepared.decision.outcome is ResumeOutcome.VERIFY:
            await confirm_read_at_full_offset(session)
        while True:
            step = await context.copies.transfer(
                copy_id, session, context.segment_size)
            if step.plan.outcome is SegmentOutcome.ALL_COMMITTED:
                break
            if step.saved is None:
                raise ConsistencyError(
                    "段推进未携带保存事实，拷贝端口契约不一致")
            if step.saved.disposition is SegmentSaveDisposition.SKIPPED:
                result = InputStep(
                    InputPhase.OWNER_SKIPPED, copy_id=copy_id,
                    reason=step.saved.reason)
                break
    except (CopySegmentError, ConsistencyError) as error:
        result = InputStep(InputPhase.SEGMENT_FAILED, copy_id=copy_id,
                           error=error, source_failed=isinstance(error, CopySegmentError) and error.source_failed)
    except BaseException as error:
        execution_error = error
        raise
    finally:
        original_error = (execution_error if execution_error is not None else
                          result.error if result is not None else None)
        end = await stop_read_session(session, original_error=original_error)
        if context.on_read_end is not None:
            context.on_read_end(end, session.position() == facts.source_size)
    if result is not None:
        return replace(result, read_end=end, stop_requested=True, content_complete=session.position() == facts.source_size)
    if end.error is not None:
        return InputStep(InputPhase.SEGMENT_FAILED, copy_id=copy_id, read_end=end,
                         error=RuntimeError(end.error), source_failed=end.error != "stopped", stop_requested=True,
                         content_complete=session.position() == facts.source_size)
    return replace(await _complete_input(context, copy_id, facts), read_end=end, stop_requested=True, content_complete=True)

